CREATE TABLE IF NOT EXISTS "cache_entries" ("id" text primary key, "key" text not null, "version" text not null, "updatedAt" bigint not null, "locationId" text not null references "storage_locations" ("id") on delete cascade, "scope" text not null, "repoId" text not null);
